package build

import (
	"crypto/sha256"
	"encoding/hex"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"testing"
)

// freezeGitDest is where fetch-base writes the helper. Like the glab shim it is
// generated by a printf block, so it is reassembled from the Dockerfile rather
// than read off disk — and it is *run*, because what it has to get right is a
// property of the bytes it leaves behind and every way of getting it wrong so
// far has been spelled correctly enough to satisfy a needle.
// → CONTEXT.md "Fetch Nondeterminism"
const freezeGitDest = "/usr/local/bin/freeze-git"

// gitIn runs a git command in dir with a fixed identity and clock, so nothing
// the harness itself creates carries the test's wall time.
func gitIn(t *testing.T, dir string, args ...string) string {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(),
		"GIT_AUTHOR_NAME=t", "GIT_AUTHOR_EMAIL=t@example.com",
		"GIT_COMMITTER_NAME=t", "GIT_COMMITTER_EMAIL=t@example.com",
		"GIT_AUTHOR_DATE=@1000000000 +0000", "GIT_COMMITTER_DATE=@1000000000 +0000",
	)
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %s (in %s): %v\n%s", strings.Join(args, " "), dir, err, out)
	}
	return strings.TrimSpace(string(out))
}

// originRepo builds a small upstream with enough near-identical files that
// packing it has real delta and compression decisions to make.
func originRepo(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	gitIn(t, dir, "init", "--initial-branch=main", "--quiet")
	for i := range 40 {
		name := filepath.Join(dir, "file"+string(rune('a'+i%26))+string(rune('0'+i/26))+".txt")
		body := strings.Repeat("the quick brown fox jumps over the lazy dog\n", 200+i)
		if err := os.WriteFile(name, []byte(body), 0o644); err != nil {
			t.Fatalf("write %s: %v", name, err)
		}
	}
	gitIn(t, dir, "add", "-A")
	gitIn(t, dir, "commit", "--quiet", "-m", "content")
	return dir
}

// checkoutWithPack clones origin over the git transport — so the working copy
// receives a real pack rather than hard-linked loose objects — and then repacks
// it at the given zlib level. The level is the seam: it stands in for two
// upload-pack responses that chose different compression for the same objects,
// which is what two `--no-cache` builds of fetch-brew were measured producing
// (identical write order, identical delta bases, different sizes in pack).
func checkoutWithPack(t *testing.T, origin string, compression string) string {
	t.Helper()
	dir := filepath.Join(t.TempDir(), "work")
	gitIn(t, ".", "clone", "--quiet", "--no-local", origin, dir)
	// -F, or the level is inert: a plain repack reuses the received objects'
	// compressed bytes verbatim, which is the very behaviour under test. -n for
	// the same reason the helper passes it: update-server-info would write a
	// dumb-HTTP `objects/info/packs` naming this pack, and neither a clone nor a
	// fetch creates that file in the stages this stands in for.
	gitIn(t, dir, "-c", "core.compression="+compression, "repack", "-adFqn")
	return dir
}

// treeDigest hashes every path under root with its mode and content (and a
// symlink's target), so two trees compare equal only if what a `COPY --link`
// layer would carry is equal. Mtimes are excluded deliberately: freeze-mtimes
// owns those, and freeze-git runs before it.
func treeDigest(t *testing.T, root string) string {
	t.Helper()
	var entries []string
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, relErr := filepath.Rel(root, path)
		if relErr != nil {
			return relErr
		}
		if rel == "." {
			return nil
		}
		info, infoErr := d.Info()
		if infoErr != nil {
			return infoErr
		}
		line := rel + "\x00" + info.Mode().String() + "\x00"
		switch {
		case d.IsDir():
			line += "dir"
		case info.Mode()&os.ModeSymlink != 0:
			target, readErr := os.Readlink(path)
			if readErr != nil {
				return readErr
			}
			line += "link:" + target
		default:
			content, readErr := os.ReadFile(path)
			if readErr != nil {
				return readErr
			}
			sum := sha256.Sum256(content)
			line += hex.EncodeToString(sum[:])
		}
		entries = append(entries, line)
		return nil
	})
	if err != nil {
		t.Fatalf("walk %s: %v", root, err)
	}
	sort.Strings(entries)
	sum := sha256.Sum256([]byte(strings.Join(entries, "\n")))
	return hex.EncodeToString(sum[:])
}

// TestFreezeGitMakesACheckoutAFunctionOfItsCommit is the behavioural gate on
// the helper `fetch-omz` and `fetch-brew` run over every checkout they ship.
//
// Both stages keep `.git` because they have to — Homebrew *is* a git checkout
// and `omz update` needs one — so the reproducibility their `COPY --link`
// layer is supposed to have (ADR 0002, "Fetch Nondeterminism" in CONTEXT.md)
// has to be bought inside the repository rather than by deleting it. Three
// things in a fresh checkout are written by the clock or by the far end and
// not by the pinned commit, and the helper answers each: the pack (whatever
// upload-pack chose to send, recompressed here), the reflog (a wall-clock
// timestamp per line, dropped), and the index (the ctime/inode of every file
// the checkout wrote, read back from HEAD with those fields zeroed).
//
// So the assertion is that two checkouts of the same commit that disagree
// about all three come out byte-identical, and still behave like the working
// repository the image ships.
func TestFreezeGitMakesACheckoutAFunctionOfItsCommit(t *testing.T) {
	script := filepath.Join(t.TempDir(), "freeze-git")
	if err := os.WriteFile(script, []byte(extractPrintfScript(t, freezeGitDest)), 0o755); err != nil {
		t.Fatalf("write freeze-git: %v", err)
	}

	origin := originRepo(t)
	head := gitIn(t, origin, "rev-parse", "HEAD")

	// Two checkouts of the same commit whose packs were compressed differently.
	fast := checkoutWithPack(t, origin, "1")
	tight := checkoutWithPack(t, origin, "9")
	if treeDigest(t, filepath.Join(fast, ".git")) == treeDigest(t, filepath.Join(tight, ".git")) {
		t.Fatal("the two checkouts are already identical before freeze-git ran — the harness no longer reproduces the divergence it is meant to normalise")
	}

	for _, repo := range []string{fast, tight} {
		cmd := exec.Command("/bin/sh", script, repo)
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("freeze-git %s: %v\n%s", repo, err, out)
		}
	}

	if got, want := treeDigest(t, filepath.Join(fast, ".git")), treeDigest(t, filepath.Join(tight, ".git")); got != want {
		t.Errorf("freeze-git left two checkouts of %s differing (%s vs %s), so the stage's COPY --link layer moves on every cache miss; `repack -f` in place of -F is the usual way to get here → CONTEXT.md \"Fetch Nondeterminism\"", head, got, want)
	}

	// Still the repository the image ships: same commit, clean worktree, and a
	// reflog git will recreate on the next ref update rather than one missing
	// piece of state that makes `brew update` or `omz update` fail.
	for _, repo := range []string{fast, tight} {
		if got := gitIn(t, repo, "rev-parse", "HEAD"); got != head {
			t.Errorf("%s: HEAD is %s, want %s — freeze-git moved the checkout off its pinned commit", repo, got, head)
		}
		if got := gitIn(t, repo, "status", "--porcelain"); got != "" {
			t.Errorf("%s: worktree is not clean after freeze-git:\n%s\n(the index was read back from HEAD with stat data zeroed, so git must fall through to comparing content and find no change)", repo, got)
		}
		if _, err := os.Stat(filepath.Join(repo, ".git", "logs")); !os.IsNotExist(err) {
			t.Errorf("%s: .git/logs survived freeze-git — every reflog line carries a wall-clock timestamp", repo)
		}
		gitIn(t, repo, "commit", "--quiet", "--allow-empty", "-m", "probe")
		if _, err := os.Stat(filepath.Join(repo, ".git", "logs", "HEAD")); err != nil {
			t.Errorf("%s: git did not recreate the reflog on a ref update (%v) — dropping it has to be a normalisation, not a mutilation", repo, err)
		}
	}
}

// treeCreatingRE matches a git command that materialises a working tree — the
// two patterns the image uses (`clone`, and `checkout FETCH_HEAD` after a
// pinned-sha fetch) and any future third that reaches a tree the same way.
var treeCreatingRE = regexp.MustCompile(`\bgit\b[^;]*\b(clone|checkout)\b`)

// dockerfileStages splits the embedded Dockerfile on its FROM lines and returns
// each stage's body with comment lines removed, keyed by the FROM line itself.
// Comments have to go: several of them quote `git clone` while describing it.
func dockerfileStages(t *testing.T) map[string][]string {
	t.Helper()
	stages := map[string][]string{}
	var current string
	for _, line := range strings.Split(readAsset(t, "Dockerfile"), "\n") {
		if strings.HasPrefix(line, "FROM ") {
			current = line
			stages[current] = nil
			continue
		}
		if current == "" || strings.HasPrefix(strings.TrimSpace(line), "#") {
			continue
		}
		stages[current] = append(stages[current], line)
	}
	if len(stages) == 0 {
		t.Fatal("Dockerfile: no FROM lines found — the parse is broken, not the file")
	}
	return stages
}

// TestGitCheckoutStagesCallFreezeGit holds the call sites, which the helper's
// own test cannot: freeze-git could be perfect and still be deleted from
// fetch-brew without a single test going red.
//
// The rule it encodes is per stage rather than per file, because "the
// Dockerfile mentions freeze-git somewhere" is satisfied by fetch-base, which
// only writes it. A stage that materialises a git working tree must invoke it
// at least once per tree, and every invocation must come before the stage's
// `chmod -R a+rwX` (which has to cover the pack and index freeze-git writes)
// and before `freeze-mtimes` (which stamps what it leaves behind).
// → CONTEXT.md "Fetch Nondeterminism"
func TestGitCheckoutStagesCallFreezeGit(t *testing.T) {
	var stagesWithTrees int
	for from, body := range dockerfileStages(t) {
		var trees, calls, lastCall, chmodAt, freezeAt int
		lastCall, chmodAt, freezeAt = -1, -1, -1
		for i, line := range body {
			if treeCreatingRE.MatchString(line) {
				trees++
			}
			if strings.HasPrefix(strings.TrimSpace(line), "freeze-git ") {
				calls++
				lastCall = i
			}
			if strings.Contains(line, "chmod -R a+rwX") && chmodAt < 0 {
				chmodAt = i
			}
			if strings.Contains(line, "freeze-mtimes") && freezeAt < 0 {
				freezeAt = i
			}
		}
		if trees == 0 {
			if calls > 0 {
				t.Errorf("%s: calls freeze-git %d time(s) but creates no git working tree — the parse or the stage is wrong", from, calls)
			}
			continue
		}
		stagesWithTrees++

		if calls < trees {
			t.Errorf("%s: materialises %d git working tree(s) but calls freeze-git %d time(s) — every checkout this stage ships has to be normalised, or its COPY --link layer moves on every cache miss", from, trees, calls)
		}
		if chmodAt >= 0 && lastCall > chmodAt {
			t.Errorf("%s: freeze-git runs after `chmod -R a+rwX` — the pack and index it writes would keep the fetch stage's permissions and break for any host UID but the baked one", from)
		}
		if freezeAt >= 0 && lastCall > freezeAt {
			t.Errorf("%s: freeze-git runs after freeze-mtimes — the files it writes would keep the build clock", from)
		}
	}
	// Anti-vacuity, without a floor tied to today's stage list: a rename that
	// makes the parse match nothing must not pass by arithmetic.
	if stagesWithTrees == 0 {
		t.Error("no stage was found to materialise a git working tree — the parse is broken, not the Dockerfile")
	}
}

// runFreezeGit runs the reassembled helper and reports its exit code.
func runFreezeGit(t *testing.T, args ...string) (code int, output string) {
	t.Helper()
	script := filepath.Join(t.TempDir(), "freeze-git")
	if err := os.WriteFile(script, []byte(extractPrintfScript(t, freezeGitDest)), 0o755); err != nil {
		t.Fatalf("write freeze-git: %v", err)
	}
	cmd := exec.Command("/bin/sh", append([]string{script}, args...)...)
	out, err := cmd.CombinedOutput()
	if err != nil {
		var ee *exec.ExitError
		if !asExitError(err, &ee) {
			t.Fatalf("run freeze-git: %v (output %q)", err, out)
		}
		code = ee.ExitCode()
	}
	return code, string(out)
}

// TestFreezeGitRefusesADirectoryThatIsNotARepository is the guard on how the
// helper names the repository it operates on.
//
// `git -C <dir>` does not mean "this repository", it means "start discovery
// here" — and discovery walks *up*. The OMZ plugins are checked out inside the
// OMZ working tree, so under -C a plugin that failed to become a repository
// would not fail: git would find the OMZ repository above it and repack and
// read-tree that instead, silently, on a green build. Naming --git-dir and
// --work-tree is what makes the miss fatal.
func TestFreezeGitRefusesADirectoryThatIsNotARepository(t *testing.T) {
	parent := originRepo(t)
	before := treeDigest(t, filepath.Join(parent, ".git"))

	// The shape that matters: a non-repository nested inside a real one.
	nested := filepath.Join(parent, "custom", "plugins", "not-a-repo")
	if err := os.MkdirAll(nested, 0o755); err != nil {
		t.Fatalf("mkdir %s: %v", nested, err)
	}

	code, out := runFreezeGit(t, nested)
	if code == 0 {
		t.Errorf("freeze-git accepted %s, which has no .git — under `git -C` it would have found the repository above it and normalised the wrong tree; output:\n%s", nested, out)
	}
	if after := treeDigest(t, filepath.Join(parent, ".git")); after != before {
		t.Errorf("freeze-git touched the enclosing repository at %s (%s → %s) — it walked up instead of failing", parent, before, after)
	}
}

// TestFreezeGitRefusesAnEmptyArgumentList pins the other silent success: a
// `for repo in "$@"` over nothing is a no-op that exits 0, so a call site that
// lost its argument through a shell-expansion mistake would normalise nothing
// and report success.
func TestFreezeGitRefusesAnEmptyArgumentList(t *testing.T) {
	if code, out := runFreezeGit(t); code == 0 {
		t.Errorf("freeze-git exited 0 with no repository to normalise; output:\n%s", out)
	}
}
